mapper.insert:
INSERT INTO orders
SET user_id = #{userId}
, store_id = #{storeId}
, address = #{address}
, amount = #{amount}

mapper.select:
SELECT o.id,o.user_id,s.`name`,m.`name` AS menuName ,om.quantity,m.price,o.amount,o.`status` FROM orders o JOIN order_menus om ON o.id = om.order_id LEFT JOIN stores s ON o.store_id = s.id JOIN menus m ON om.menu_id = m.id
o.user_id = #{userId}
AND o.store_id = #{storeId}

mapper.update:
UPDATE orders
SET is_deleted = 1
WHERE	id = #{orderId}
AND user_id = #{userId};
